        <div class="address-box">
          <div v-for="(item,index) in addressList" :key="index" class="card">
            <div class="title">
              <!-- <span>{{ item.urlback }}</span> -->
              <span style="font-size: 14px;font-family: PingFangSC-Semibold;font-weight: 600;">Tron(TRC20)</span>
              <div class="deleteBtn" @click="deleteAddress(item.usdturl)" />
            </div>
            <div class="address">{{ item.usdturl }}</div>
          </div>
        </div>
        <van-button
          style="
                background-color: transparent;
                height: 48px;
                line-height: 48px;
                width: 295px;
                text-align: center;
                font-family: PingFangSC-Regular;
                font-size: 14px;
                color: #00B7FF;
                font-weight: 400;
                margin: auto;
                border: none;"
          block
          type="info"
          @click="showAddressPop"
        >{{ $t('aqzx.aqzx32') }}</van-button>
        <!-- <div class="add">
          <div class="addBtn" @click="addAddressVisible=true" />
          <div class="text">添加新的提现地址</div>
        </div> -->
      </div>
    </div>
    <!-- 弹窗组件 -->
    <van-popup
      v-model="addAddressVisible"
      round
      closeable
      close-icon="close"
      position="bottom"
    >
      <div class="address-pop">
        <div class="title">{{ $t('aqzx.aqzx33') }}</div>
        <div class="main">
          <van-form @submit="onSubmit" @failed="onFailed">
            <div class="item-title">{{ $t('aqzx.aqzx34') }}</div>
            <div class="blockChain">
              <van-dropdown-menu style="border-radius:10px">
                <van-dropdown-item v-model="blockChain" disabled :options="blockChainOption" />
              </van-dropdown-menu>
            </div>
            <div class="item-title">{{ $t('aqzx.aqzx35') }}</div>
            <div class="content">
              <van-field
                v-model="addressInfo"
                autocomplete="off"
                type="text"
                label=""
                :placeholder="$t('aqzx.aqzx36')"
                :rules="[{ required: true, message: $t('aqzx.aqzx36') }]"
              />
