<script>
import TitleLine from '../modules/TitleLine'
import { getWebDrawurl, addWebDrawurl, delWebDrawurl } from '@/api/user'
export default {
  components: {
    TitleLine
  },
  data() {
    return {
      title: this.$t('aqzx.aqzx30'),
      bindNum: '',
      addressList: [],
      addAddressVisible: false,
      blockChain: 0,
      blockChainOption: [
        { text: 'TRC-20', value: 0 }
      ],
      addressInfo: '',
      password: '',
      passwordType: 'password'

    }
  },
  created() {
    this.updateWebDrawurl()
  },
  methods: {
    showAddressPop() {
      this.addAddressVisible = true
    },
    switchPasswordType() {
      this.passwordType = this.passwordType === 'password' ? 'text' : 'password'
    },
    onSubmit() {
      // const param = {
      //   usdturl: this.addressInfo
      //   // drawpwd: this.password
      // }
      if (!this.isTrxAddress(this.addressInfo)) {
        this.$toast('地址校验失败，请输入正确格式的地址！')
        return false
      }
      addWebDrawurl({ usdturl: this.addressInfo, drawpwd: this.password }).then(res => {
        if (res.status === '1') {
          this.$toast('添加成功')
        } else {
          this.$toast('添加失败')
        }
        this.addAddressVisible = false
        this.updateWebDrawurl()
      })
    },
    deleteAddress(usdturl) {
      delWebDrawurl({ usdturl: usdturl }).then(res => {
        if (res.status === '1') {
          this.$toast('删除成功')
        } else {
          this.$toast('删除失败')
        }
        this.updateWebDrawurl()
      })
    },
    onFailed(errorInfo) {
      console.log('failed', errorInfo)
      this.$toast(errorInfo.errors[0].message)
    },
    getContainer() {
      return document.querySelector('.van-dropdown-menu')
    },
    updateWebDrawurl() {
      getWebDrawurl().then(res => {
        this.addressList = res.datalist
        this.bindNum = res.datalist.length
      })
    },
    isTrxAddress(base58Str) {
      if (typeof (base58Str) !== 'string') { return false }
      if (base58Str.length !== 34) { return false }
      let address = this.decode58(base58Str)
      if (address.length !== 25) { return false }
      if (address[0] !== 0x41) { return false }
      const checkSum = address.slice(21)
      address = address.slice(0, 21)
      const SHA256 = require('js-sha256').sha256
      const hash0 = SHA256(address)
      const hash1 = SHA256(hash0)
      const checkSum1 = hash1.slice(0, 4)
      // if (checkSum[0] === checkSum1[0] && checkSum[1] === checkSum1[1] && checkSum[2] ===
      //   checkSum1[2] && checkSum[3] === checkSum1[3]
      // ) {
      //   return true
      // }

      return true
    },
    encode58(buffer) {
      const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
      const ALPHABET_MAP = {}
      for (let i = 0; i < ALPHABET.length; i++) { ALPHABET_MAP[ALPHABET.charAt(i)] = i }
      const BASE = 58
      if (buffer.length === 0) { return '' }
      let i
      let j
      const digits = [0]
      for (i = 0; i < buffer.length; i++) {
        for (j = 0; j < digits.length; j++) { digits[j] <<= 8 }
        digits[0] += buffer[i]
        let carry = 0
        for (j = 0; j < digits.length; ++j) {
          digits[j] += carry
          carry = (digits[j] / BASE) | 0
          digits[j] %= BASE
        }
        while (carry) {
          digits.push(carry % BASE)
          carry = (carry / BASE) | 0
        }
      }
      for (i = 0; buffer[i] === 0 && i < buffer.length - 1; i++) { digits.push(0) }
      return digits.reverse().map(digit => ALPHABET[digit]).join('')
    },
    decode58(string) {
      const ALPHABET = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
      const ALPHABET_MAP = {}
      for (let i = 0; i < ALPHABET.length; i++) { ALPHABET_MAP[ALPHABET.charAt(i)] = i }
      const BASE = 58
      if (string.length === 0) { return [] }
      let i
      let j
      const bytes = [0]
      for (i = 0; i < string.length; i++) {
        const c = string[i]
        if (!(c in ALPHABET_MAP)) {
          // throw new Error('Non-base58 character')
          return false
        }
        for (j = 0; j < bytes.length; j++) { bytes[j] *= BASE }
        bytes[0] += ALPHABET_MAP[c]
        let carry = 0
        for (j = 0; j < bytes.length; ++j) {
          bytes[j] += carry
          carry = bytes[j] >> 8
          bytes[j] &= 0xff
        }
        while (carry) {
          bytes.push(carry & 0xff)
          carry >>= 8
        }
      }
      for (i = 0; string[i] === '1' && i < string.length - 1; i++) { bytes.push(0) }
      return bytes.reverse()
    }
  }

}
</script>
